.pc-lb__btn { position: absolute; width: 48px; height: 48px; border-radius: 50%; border: 1px solid rgb(255 255 255 / .2); background: rgb(255 255 255 / .06); color: #fff; display: grid; place-items: center; cursor: pointer; transition: background .3s, color .3s, border-color .3s; }
.pc-lb__btn:hover, .pc-lb__btn:focus-visible { background: #beda52; border-color: #beda52; color: #11150a; }
.pc-lb__close { top: 18px; right: 18px; }
.pc-lb__prev { left: 18px; top: 50%; margin-top: -24px; }
.pc-lb__next { right: 18px; top: 50%; margin-top: -24px; }
@media (max-width: 699px) { .pc-lb__prev, .pc-lb__next { top: auto; bottom: 18px; margin: 0; } }
@keyframes pc-lb-in { from { opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .pc-lb[open] { animation: none; } }

/* hero backdrop: one solid off-white fill, edge to edge and behind the fixed header, with generous padding
   between the header and the hero content */
.pc-hero { background: #f5f3eb; }
.pc-page .sec.pc-hero { padding-top: calc(var(--head-h) + clamp(56px, 7vw, 110px)); }
:root:not([data-theme='light']) .pc-hero { background: #0c0c0a; }

/* ---- video testimonials: 9:16 reel cards in a scroll-snap row (4 visible on desktop), lime play button ---- */
.pc-tst { list-style: none; margin: 0; padding: 0 0 8px; display: flex; gap: clamp(12px, 1.6vw, 20px); overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; overscroll-behavior-x: contain; }
.pc-tst::-webkit-scrollbar { display: none; }
.pc-tst__card { flex: none; width: calc((100% - 3 * clamp(12px, 1.6vw, 20px)) / 4); scroll-snap-align: start; }
.pc-tst__media { position: relative; display: block; width: 100%; aspect-ratio: 9 / 16; padding: 0; border: 0; border-radius: var(--r-card); overflow: hidden; background: #111; cursor: pointer; box-shadow: 0 0 0 1px var(--edge); transition: box-shadow .5s var(--ease), translate .5s var(--ease); }
.pc-tst__media img, .pc-tst__media video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.pc-tst__media img { transition: transform .8s var(--ease); }
.pc-tst__media video { background: #000; }
.pc-tst__play { position: absolute; left: 50%; top: 50%; width: 64px; height: 64px; margin: -32px 0 0 -32px; border-radius: 50%; display: grid; place-items: center; background: #beda52; color: #11150a; box-shadow: 0 0 0 8px rgb(190 218 82 / .28); transition: transform .4s var(--ease), box-shadow .4s var(--ease); }
.pc-tst__media.is-playing { cursor: default; }
.pc-tst__media:focus-visible { outline: 2px solid #beda52; outline-offset: 3px; }
@media (hover: hover) {
  .pc-tst__media:not(.is-playing):hover { translate: 0 -4px; box-shadow: 0 0 0 2px #beda52, 0 20px 40px -24px rgb(95 120 20 / .7); }
  .pc-tst__media:not(.is-playing):hover img { transform: scale(1.05); }
  .pc-tst__media:hover .pc-tst__play { transform: scale(1.1); box-shadow: 0 0 0 12px rgb(190 218 82 / .35); }
}
@media (max-width: 899px) { .pc-tst__card { width: calc((100% - clamp(12px, 1.6vw, 20px)) / 2.3); } }
@media (max-width: 599px) {
  .pc-tst { margin-inline: calc(-1 * var(--gx)); padding-inline: var(--gx); scroll-padding-inline: var(--gx); }
  .pc-tst__card { width: 68vw; }
  .pc-tst__play { width: 54px; height: 54px; margin: -27px 0 0 -27px; }
}

/* ---- hero podcast icons: "On air" pill with live dot + equalizer, mic and headphones stickers on the photo ---- */
.pc-hero__tagrow { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 22px; }
.pc-onair { display: inline-flex; align-items: center; gap: 9px; height: 36px; padding: 0 14px 0 12px; border-radius: var(--r-pill); background: #11150a; color: #fff; font-size: 12px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; }
.pc-onair__dot { width: 8px; height: 8px; border-radius: 50%; background: #ff3b30; box-shadow: 0 0 0 0 rgb(255 59 48 / .6); animation: pc-live 1.6s ease-out infinite; }
@keyframes pc-live { 70% { box-shadow: 0 0 0 7px rgb(255 59 48 / 0); } 100% { box-shadow: 0 0 0 0 rgb(255 59 48 / 0); } }

.pc-hero__media { position: relative; }
.pc-stk { position: absolute; z-index: 2; display: grid; place-items: center; border-radius: 50%; pointer-events: none; }
.pc-stk svg { width: 100%; height: 100%; overflow: visible; }
.pc-stk--mic { left: clamp(-36px, -2.4vw, -18px); bottom: clamp(-30px, -2vw, -16px); width: clamp(88px, 9vw, 124px); aspect-ratio: 1; background: #beda52; box-shadow: 0 0 0 6px #f5f3eb, 0 18px 34px -16px rgb(60 80 10 / .55); animation: pc-bob 5s ease-in-out infinite; }
.pc-stk--hp { right: clamp(-26px, -1.8vw, -14px); top: clamp(-26px, -1.8vw, -14px); width: clamp(64px, 6.4vw, 88px); aspect-ratio: 1; background: #11150a; box-shadow: 0 0 0 6px #f5f3eb, 0 16px 30px -16px rgb(0 0 0 / .5); animation: pc-bob 6s ease-in-out -2s infinite; }
:root:not([data-theme='light']) .pc-stk--mic, :root:not([data-theme='light']) .pc-stk--hp { box-shadow: 0 0 0 6px #0c0c0a; }
:root:not([data-theme='light']) .pc-stk--hp { background: #1b1f12; }
.pc-stk__waves path { transform-box: fill-box; opacity: 0; animation: pc-wave 2.2s ease-out infinite; }
.pc-stk__waves path:nth-child(odd) { transform-origin: right center; }
.pc-stk__waves path:nth-child(n+3):nth-child(odd), .pc-stk__waves path:nth-child(4) { transform-origin: left center; }
.pc-stk__waves .w2 { animation-delay: .35s; }
.pc-stk__mic { transform-box: fill-box; transform-origin: 50% 100%; animation: pc-sway 3.2s ease-in-out infinite; }
.pc-stk__hp { transform-box: fill-box; transform-origin: 50% 70%; animation: pc-beat 1.2s ease-in-out infinite; }
.pc-stk__notes circle { animation: pc-note 1.2s ease-in-out infinite; }
@keyframes pc-bob { 0%, 100% { translate: 0 0; rotate: -4deg; } 50% { translate: 0 -8px; rotate: 4deg; } }
@keyframes pc-wave { 0% { opacity: 0; transform: scale(.7); } 30% { opacity: 1; } 100% { opacity: 0; transform: scale(1.15); } }
@keyframes pc-sway { 0%, 100% { rotate: -5deg; } 50% { rotate: 5deg; } }
@keyframes pc-beat { 0%, 100% { scale: 1; } 15% { scale: 1.08; } 30% { scale: 1; } 45% { scale: 1.05; } }
@keyframes pc-note { 0%, 100% { opacity: .2; } 50% { opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  .pc-onair__dot, .pc-stk, .pc-stk__waves path, .pc-stk__mic, .pc-stk__hp, .pc-stk__notes circle { animation: none; }
  .pc-stk__waves path { opacity: 1; }
}
@media (max-width: 899px) { .pc-stk--mic { left: -6px; bottom: -22px; } .pc-stk--hp { right: -6px; top: -18px; } }

/* gallery with the real shoot photos (all landscape): faces sit in the upper-middle, so crop from there */
.pc-gal__btn img { object-position: 50% 35%; }
.pc-gal__item--tall { grid-row: span 1; }
@media (max-width: 599px) {
  .pc-onair { height: 30px; padding: 0 11px 0 10px; gap: 7px; font-size: 11px; }
  .pc-hero__tagrow { gap: 8px; margin-bottom: 18px; }
  .pc-person__tag, .pc-ep__new { font-size: 11px; padding: 5px 11px; }
  .proc__tag { font-size: 12px; }
}

/* "On air" beside the now-black chip: a white outlined pill in light mode so the two read as a pair, dark in dark mode */
:root[data-theme='light'] .pc-onair { background: #fff; color: #11150a; box-shadow: inset 0 0 0 1px #dcdcd4; }
/* "New episode" badge sits on a photo: black so it doesn't echo the lime buttons */
.pc-ep__new { background: #11150a; color: #fff; }

/* testimonials: no outline at rest or on hover, just the lift and a soft shadow */
.pc-tst__media { box-shadow: none; }
@media (hover: hover) { .pc-tst__media:not(.is-playing):hover { box-shadow: 0 20px 40px -24px rgb(0 0 0 / .45); } }
/* gallery: the four wide photos span two rows so they sit close to their natural 3:2 shape; on phones rows
   shrink to 30vw so the small tiles stay landscape too */
.pc-gal__item--wide { grid-row: span 2; }
@media (max-width: 699px) { .pc-gal { grid-auto-rows: 30vw; } }

/* ---- community banner (live): studio photo, dark side fades for legibility, text left, stats right ---- */
.pc-cb { position: relative; isolation: isolate; overflow: hidden; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 32px;
  min-height: clamp(340px, 33vw, 480px); padding: clamp(28px, 4vw, 56px) clamp(24px, 3.4vw, 50px); border-radius: var(--r-card); color: #fff; background: #0b1414; }
.pc-cb__bg, .pc-cb__bg img { position: absolute; inset: 0; z-index: -2; width: 100%; height: 100%; object-fit: cover; }
.pc-cb::before { content: ''; position: absolute; inset: 0; z-index: -1;
  background: linear-gradient(90deg, rgb(4 12 12 / .82) 0%, rgb(4 12 12 / .45) 32%, rgb(4 12 12 / 0) 52%, rgb(4 12 12 / 0) 68%, rgb(4 12 12 / .7) 84%, rgb(4 12 12 / .85) 100%); }
.pc-cb__h { margin: 0; font-size: clamp(1.9rem, 1.1rem + 2.4vw, 3.1rem); font-weight: 700; line-height: 1.08; letter-spacing: -0.025em; text-shadow: 0 2px 18px rgb(0 0 0 / .35); }
.pc-cb__big { font-size: 1.75em; letter-spacing: -0.04em; color: #f5d214; margin-right: .12em; }
.pc-cb__p { margin: 14px 0 0; font-size: clamp(1rem, .9rem + .4vw, 1.25rem); color: rgb(255 255 255 / .92); }
.pc-cb__row { display: flex; flex-wrap: wrap; align-items: center; gap: 18px; margin-top: clamp(20px, 2.4vw, 30px); }
.pc-cb__faces { display: flex; }
.pc-cb__faces img { width: clamp(40px, 3.6vw, 52px); height: clamp(40px, 3.6vw, 52px); border-radius: 50%; object-fit: cover; object-position: 50% 20%; border: 2px solid #fff; margin-left: -12px; background: #222; }
.pc-cb__faces img:first-child { margin-left: 0; }
.pc-cb__sub { display: inline-flex; align-items: center; gap: 14px; height: clamp(50px, 4.4vw, 62px); padding: 0 24px 0 22px; border-radius: 999px; background: #fff; color: #11150a; font-size: clamp(15px, 1.1vw, 17px); font-weight: 600; white-space: nowrap; transition: translate .3s var(--ease), box-shadow .3s; }
.pc-cb__yt { width: 34px; height: auto; }
.pc-cb__arr { width: 20px; height: 20px; transition: translate .3s var(--ease); }
@media (hover: hover) { .pc-cb__sub:hover { translate: 0 -2px; box-shadow: 0 14px 30px -14px rgb(0 0 0 / .6); } .pc-cb__sub:hover .pc-cb__arr { translate: 4px 0; } }
.pc-cb__sub:focus-visible { outline: 2px solid #f5d214; outline-offset: 3px; }
.pc-cb__stats { list-style: none; margin: 0; padding: 0; display: grid; min-width: 230px; }
.pc-cb__stats li { display: flex; align-items: center; gap: 16px; padding: 16px 0; font-size: clamp(1rem, .9rem + .35vw, 1.2rem); font-weight: 500; border-bottom: 1px solid rgb(255 255 255 / .22); }
.pc-cb__stats li:last-child { border-bottom: 0; }
.pc-cb__stats svg { flex: none; width: 30px; height: 30px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
@media (max-width: 1100px) {
  .pc-cb { grid-template-columns: 1fr; gap: 26px; align-items: end; min-height: 0; padding-top: clamp(150px, 40vw, 260px); }
  .pc-cb::before { background: linear-gradient(180deg, rgb(4 12 12 / .1) 0%, rgb(4 12 12 / .55) 35%, rgb(4 12 12 / .9) 62%, rgb(4 12 12 / .95) 100%); }
  .pc-cb__bg img { object-position: 60% 0; height: 70%; }
  .pc-cb__stats { grid-template-columns: repeat(4, auto); justify-content: start; column-gap: 28px; min-width: 0; }
  .pc-cb__stats li { font-size: 15px; gap: 10px; padding: 0; border: 0; white-space: nowrap; }
  .pc-cb__stats svg { width: 24px; height: 24px; }
}
@media (min-width: 700px) and (max-width: 1100px) {
  .pc-cb { padding-top: clamp(200px, 30vw, 300px); }
  .pc-cb__bg img { height: 100%; object-position: 50% 30%; }
  .pc-cb::before { background: linear-gradient(180deg, rgb(4 12 12 / 0) 15%, rgb(4 12 12 / .6) 45%, rgb(4 12 12 / .92) 75%); }
}
@media (max-width: 699px) {
  .pc-cb__stats { grid-template-columns: 1fr 1fr; column-gap: 12px; row-gap: 14px; padding-top: 18px; border-top: 1px solid rgb(255 255 255 / .2); }
  .pc-cb__stats li { font-size: 13.5px; gap: 8px; }
  .pc-cb__stats svg { width: 20px; height: 20px; }
}
@media (max-width: 420px) { .pc-cb__sub { gap: 10px; padding: 0 18px; } .pc-cb__yt { width: 28px; } }
@media (max-width: 699px) {
  .pc-cb { padding-top: 58vw; }
  .pc-cb__bg img { height: 64%; object-position: 72% 40%; }
  .pc-cb::before { background: linear-gradient(180deg, rgb(4 12 12 / 0) 0%, rgb(4 12 12 / .15) 30%, rgb(4 12 12 / .85) 52%, rgb(4 12 12 / .97) 66%); }
}
@media (max-width: 699px) {
  .pc-cb { padding-top: 66vw; }
  .pc-cb__bg img { height: 76vw; object-position: 72% 35%; }
  .pc-cb::before { background: linear-gradient(180deg, rgb(4 12 12 / 0) 0, rgb(4 12 12 / 0) 44vw, rgb(4 12 12 / .9) 70vw, rgb(4 12 12 / .97) 80vw); }
}

/* testimonial play control: off the face, bottom-left: lime play disc + "Watch story" on a glass pill over a soft fade */
.pc-tst__media::after { inset: 50% 0 0; background: linear-gradient(180deg, rgb(0 0 0 / 0), rgb(0 0 0 / .65)); }
.pc-tst__media.is-playing::after { display: none; }
.pc-tst__play { left: 14px; top: auto; bottom: 14px; z-index: 2; width: auto; height: auto; margin: 0; display: inline-flex; align-items: center; gap: 10px; padding: 5px 16px 5px 5px; border-radius: 999px;
  background: rgb(10 10 12 / .55); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); box-shadow: inset 0 0 0 1px rgb(255 255 255 / .14); color: #fff; font-size: 13px; font-weight: 600; letter-spacing: .01em; transition: gap .35s var(--ease), background .35s; }
.pc-tst__play i { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: #beda52; color: #11150a; box-shadow: 0 0 0 0 rgb(190 218 82 / .5); animation: tst-ping 2.4s ease-out infinite; transition: scale .35s var(--ease); }
.pc-tst__play i svg { translate: 1px 0; }
@keyframes tst-ping { 70% { box-shadow: 0 0 0 9px rgb(190 218 82 / 0); } 100% { box-shadow: 0 0 0 0 rgb(190 218 82 / 0); } }
@media (hover: hover) {
  .pc-tst__media:hover .pc-tst__play { transform: none; gap: 14px; background: rgb(10 10 12 / .75); box-shadow: inset 0 0 0 1px rgb(255 255 255 / .14); }
  .pc-tst__media:hover .pc-tst__play i { scale: 1.1; }
}
@media (max-width: 599px) { .pc-tst__play { width: auto; height: auto; margin: 0; font-size: 12px; } .pc-tst__play i { width: 30px; height: 30px; } }
@media (prefers-reduced-motion: reduce) { .pc-tst__play i { animation: none; } }

/* ---- latest episodes v2: nine equal cards, 3 across ---- */
.pc-eps__grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(14px, 1.6vw, 22px); }
.pc-ep, .pc-ep--lead { grid-column: auto; grid-row: auto; display: flex; flex-direction: column; padding: 0; border-radius: var(--r-card); overflow: hidden;
  background: var(--card); box-shadow: inset 0 0 0 1px var(--edge); transition: translate .5s var(--ease), box-shadow .5s var(--ease); }
.pc-ep__th { border-radius: 0; aspect-ratio: 16 / 9; }
.pc-ep__th::after { content: ''; position: absolute; inset: 55% 0 0; background: linear-gradient(180deg, rgb(0 0 0 / 0), rgb(0 0 0 / .35)); pointer-events: none; }
.pc-ep__play.yt, .pc-ep--lead .pc-ep__play.yt { inset: auto 14px 14px auto; margin: 0; width: 46px; z-index: 2; opacity: .9; transition: transform .4s var(--ease), opacity .3s; }
.pc-ep__new { left: 14px; top: 14px; z-index: 2; display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 999px; background: rgb(10 10 12 / .7); -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); color: #fff; font-size: 12px; font-weight: 600; }
.pc-ep__new i { width: 7px; height: 7px; border-radius: 50%; background: #beda52; box-shadow: 0 0 8px #beda52; }
.pc-ep__body, .pc-ep--lead .pc-ep__body { flex: 1; display: flex; flex-direction: column; padding: clamp(18px, 1.8vw, 24px); }
.pc-ep__tag { font-size: 11.5px; letter-spacing: .08em; }
.pc-ep h3, .pc-ep--lead h3 { margin: 8px 0 0; max-width: none; font-size: clamp(1.02rem, .95rem + .3vw, 1.18rem); font-weight: 500; line-height: 1.32; letter-spacing: -0.015em; }
.pc-ep__go { margin-top: auto; padding-top: 18px; border-top: 1px solid var(--edge); display: flex; justify-content: space-between; align-items: center; width: 100%; font-size: 13px; font-weight: 600; color: var(--ink); }
.pc-ep h3 { margin-bottom: 20px; }
.pc-ep__go i { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--edge); color: var(--ink); transition: background .35s, color .35s, rotate .4s var(--ease), box-shadow .35s; }
@media (hover: hover) {
  .pc-ep:hover { background: var(--card); translate: 0 -5px; box-shadow: inset 0 0 0 1px var(--edge), 0 24px 44px -26px rgb(0 0 0 / .45); }
  .pc-ep:hover h3, .pc-ep:hover .pc-ep__go { color: var(--ink); }
  .pc-ep:hover .pc-ep__tag { color: #5e8a14; }
  :root:not([data-theme='light']) .pc-ep:hover .pc-ep__tag { color: #beda52; }
  .pc-ep:hover .pc-ep__th img { transform: scale(1.06); }
  .pc-ep:hover .pc-ep__play { transform: scale(1.1); opacity: 1; }
  .pc-ep:hover .pc-ep__go i { background: #beda52; color: #11150a; box-shadow: none; rotate: 45deg; }
}
@media (max-width: 999px) { .pc-eps__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 699px) { .pc-ep, .pc-ep--lead { width: 80vw; } .pc-ep__play.yt { width: 40px; } }

/* community banner: an overall dark overlay on the photo (on top of the side fades) so every line reads cleanly */
.pc-cb__bg::after { content: ''; position: absolute; inset: 0; background: rgb(3 8 8 / .45); }
.pc-cb__bg { overflow: hidden; }
@media (max-width: 699px) {
  .pc-cb { padding: 62vw 20px 22px; gap: 22px; }
  .pc-cb__h { font-size: clamp(1.7rem, 1.2rem + 2.6vw, 2.1rem); }
  .pc-cb__big { font-size: 1.6em; }
  .pc-cb__p { font-size: 15px; }
  .pc-cb__row { gap: 14px; }
  .pc-cb__faces img { width: 38px; height: 38px; margin-left: -10px; }
  .pc-cb__sub { width: 100%; justify-content: center; height: 52px; font-size: 15px; }
}

/* ---- featured stack: episode cards that stick and stack ---- */
.pc-fstack { list-style: none; margin: 0; padding: 0; display: grid; gap: clamp(24px, 4vh, 48px); }
.pc-fcard { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: clamp(24px, 3.4vw, 52px); align-items: center;
  padding: clamp(14px, 1.4vw, 20px); padding-right: clamp(20px, 3vw, 44px); border-radius: calc(var(--r-card) + 6px); background: var(--card); box-shadow: inset 0 0 0 1px var(--edge), 0 24px 50px -30px rgb(0 0 0 / .35);
  transform-origin: 50% 0; will-change: transform; }
.pc-fcard .pc-feat__frame { aspect-ratio: 16 / 9; border-radius: var(--r-card); box-shadow: none; }
.pc-fcard .pc-feat__title { font-size: clamp(1.6rem, 1.1rem + 1.7vw, 2.6rem); }
@media (max-width: 899px) {
  .pc-fcard { grid-template-columns: 1fr; padding: 12px 12px 22px; gap: 18px; }
  .pc-fcard__body { padding: 0 8px; }
}
@media (max-height: 760px) and (min-width: 900px) { .pc-fcard .pc-feat__sub { display: none; } }
/* JS on (featuredStack): each card sticks under the header and the next one scrolls up over it in normal
   flow (no pin, so the page above/below stays visible and no empty pin-spacer). Each later card sticks a
   little lower so the edge of the one behind still shows. */
/* --fs-top follows the site header: just under it while it shows, near the top of the screen while it's hidden
   on scroll-down (no empty band). */
#featured { --fs-top: calc(var(--head-h) + 12px); }
:root:has(.hd.is-hidden) #featured { --fs-top: 16px; }
.pc-fstack.is-stacked > .pc-fcard { position: sticky; top: calc(var(--fs-top) + 8px); transition: top .55s var(--ease); }
.pc-fstack.is-stacked > .pc-fcard + .pc-fcard { top: calc(var(--fs-top) + 24px); }
@media (max-height: 760px) { .pc-fstack.is-stacked .pc-feat__sub { display: none; } }

/* Watermark words framing the stack, in the section-heading type as a faint solid fill: "Featured" up the left side,
   "Podcasts" down the right, kept beside the cards while the stack scrolls (sticky inside full-height grid columns).
   Mobile has its own treatment, see the max-width: 899px block below. */
.pc-fstage { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; column-gap: clamp(10px, 1.4vw, 22px); }
.pc-fstage > .pc-fstack { grid-column: 2; grid-row: 1; }
/* The negative margin stretches each word column past the stack by (screen - last card's stuck bottom edge), so the
   screen-tall sticky box below releases together with the last card instead of a screen-height early.
   --fc-last = the last card's height, set by featuredStack. */
.pc-fwm { grid-row: 1; pointer-events: none; user-select: none;
  margin-bottom: min(0px, calc(var(--fs-top) + 24px + var(--fc-last, 100svh) - 100svh)); }
.pc-fwm--l { grid-column: 1; }
.pc-fwm--r { grid-column: 3; }
/* A screen-tall sticky box pinned to the top, so the word sits centred between the top and bottom of the screen */
/* --fwm-fs / --fwm-col: the side words' size and column width, shared with the Latest Episodes notches below */
.pc-page { --fwm-fs: clamp(3.4rem, 1.4rem + 4vw, 6.6rem); --fwm-col: calc(var(--fwm-fs) * 0.8); }
.pc-fwm > span { position: sticky; top: 0; display: grid; place-items: center; height: 100vh; height: 100svh;
  writing-mode: vertical-rl; white-space: nowrap; font-size: var(--fwm-fs); font-weight: 700; line-height: 0.8; letter-spacing: -0.04em;
  color: rgb(255 255 255 / 0.07); }
:root[data-theme='light'] .pc-fwm > span { color: rgb(17 21 10 / 0.06); }
.pc-fwm--l > span { rotate: 180deg; }
/* Mobile: "Featured  Podcasts" is one band that sticks above the cards and doubles as the stack's progress bar:
   a lime fill sweeps through the letters, "Featured" then "Podcasts", as you scroll through the cards (--p 0..1,
   set by featuredStack). The cards stick just below the band. */
@media (max-width: 899px) {
  .pc-fstage { --wm-fs: clamp(2.2rem, 10vw, 4.4rem); --wm-h: calc(var(--wm-fs) * 1.1);
    --wm-base: rgb(255 255 255 / 0.12); --wm-fill: #beda52;
    grid-template-columns: auto auto; grid-template-rows: var(--wm-h) auto; justify-content: space-between; row-gap: 12px; }
  :root[data-theme='light'] .pc-fstage { --wm-base: rgb(17 21 10 / 0.1); --wm-fill: #8fa838; }
  .pc-fstage > .pc-fstack { grid-column: 1 / -1; grid-row: 2; }
  .pc-fwm { grid-row: 1 / 3; margin-bottom: 0; }
  .pc-fwm--r { grid-column: 2; }
  .pc-fwm > span { top: var(--fs-top); display: block; height: auto; writing-mode: horizontal-tb; rotate: none; font-size: var(--wm-fs); line-height: 1.1;
    color: transparent; -webkit-background-clip: text; background-clip: text;
    background-image: linear-gradient(90deg, var(--wm-fill) 0 var(--q), var(--wm-base) var(--q)); transition: top .55s var(--ease); }
  .pc-fwm--l > span { --q: calc(clamp(0, var(--p, 0) * 2, 1) * 100%); }
  .pc-fwm--r > span { --q: calc(clamp(0, var(--p, 0) * 2 - 1, 1) * 100%); }
  .pc-fstack.is-stacked > .pc-fcard { top: calc(var(--fs-top) + var(--wm-h) + 10px); }
  .pc-fstack.is-stacked > .pc-fcard + .pc-fcard { top: calc(var(--fs-top) + var(--wm-h) + 26px); }
}
#episodes { position: relative; z-index: 1; }
/* A covered card dims toward the page colour through this overlay (--dim, animated by featuredStack)
   rather than fading its own opacity, which let the cards behind ghost through. */
.pc-fstack.is-stacked > .pc-fcard::after { content: ''; position: absolute; inset: 0; border-radius: inherit; background: var(--bg); opacity: var(--dim, 0); pointer-events: none; }

/* ---- episodes v3: view count + date on the thumbnail, Malayalam-ready titles, giant outlined marquee ---- */
.pc-ep h3 { font-family: 'Inter', 'Noto Sans Malayalam', sans-serif; }
.pc-ep__meta { position: absolute; left: 14px; bottom: 14px; z-index: 2; padding: 5px 10px; border-radius: 999px; background: rgb(10 10 12 / .7); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); color: #fff; font-size: 11.5px; font-weight: 500; }
.pc-ep__go i { width: 34px; height: 34px; }
.pc-eps__marquee { margin: 0 calc(50% - 50vw) clamp(28px, 4vw, 52px); overflow: hidden; white-space: nowrap; pointer-events: none; }
.pc-eps__marquee span { display: inline-block; font-size: clamp(3rem, 2rem + 6vw, 8.5rem); font-weight: 700; letter-spacing: -0.04em; line-height: 1; color: transparent; -webkit-text-stroke: 1.5px var(--edge-2, rgb(0 0 0 / .14)); will-change: transform; }
:root[data-theme='light'] .pc-eps__marquee span { -webkit-text-stroke-color: rgb(17 21 10 / .14); }
:root:not([data-theme='light']) .pc-eps__marquee span { -webkit-text-stroke-color: rgb(255 255 255 / .14); }
.pc-eps__grid { perspective: 1400px; }
/* bolder arrows across the podcast page */
.pc-page .ico { stroke-width: 2.2; }
.pc-ep { translate: 0 var(--py, 0px); }

/* ---- FAQ: sticky left column (heading, studio mic photo, contact), questions on the right ---- */
.pc-faq { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); gap: clamp(32px, 5vw, 80px); align-items: start; }
.pc-faq__side { position: sticky; top: calc(var(--head-h, 96px) + 24px); display: grid; gap: 24px; }
.pc-faq__side .sh { margin-bottom: 0; }
.pc-faq__img { margin: 0; border-radius: var(--r-card); overflow: hidden; aspect-ratio: 4 / 3; }
.pc-faq__img img { width: 100%; height: 100%; object-fit: cover; object-position: 30% 50%; }
.pc-faq__ask { margin: 0; color: var(--mute); font-size: 15px; }
.pc-faq__ask a { color: var(--ink); font-weight: 600; text-decoration: underline; text-decoration-color: #beda52; text-decoration-thickness: 2px; text-underline-offset: 4px; }
.pc-faq .faq { margin: 0; }
@media (max-width: 899px) {
  .pc-faq { grid-template-columns: 1fr; }
  .pc-faq__side { position: static; }
  .pc-faq__img { aspect-ratio: 16 / 9; }
}
.pc-faq .faq { gap: 10px; } .pc-faq .faq__q { padding-block: 18px; } .pc-faq .faq__q h3 { font-size: 16px; }

/* FAQ illustration: lime blob, studio mic, sound waves, floating question bubbles */
.pc-faq__art { margin: 0; }
.pc-faq__art svg { display: block; width: 100%; max-width: 440px; height: auto; overflow: visible; }
.fa-mic { transform-box: fill-box; transform-origin: 50% 100%; animation: fa-sway 4s ease-in-out infinite; }
.fa-waves path { transform-box: fill-box; animation: fa-wave 2.4s ease-out infinite; }
.fa-waves path:nth-child(2), .fa-waves path:nth-child(4) { animation-delay: .4s; }
.fa-waves path:nth-child(-n+2) { transform-origin: right center; }
.fa-waves path:nth-child(n+3) { transform-origin: left center; }
.fa-q { animation: fa-float 5s ease-in-out infinite; }
.fa-q2 { animation-delay: -1.6s; } .fa-q3 { animation-delay: -3.2s; }
.fa-blob { transform-box: fill-box; transform-origin: center; animation: fa-blob 14s ease-in-out infinite; }
:root:not([data-theme='light']) .fa-q2 rect, :root:not([data-theme='light']) .fa-q2 path { fill: #1b1d17; stroke: #beda52; }
:root:not([data-theme='light']) .fa-q2 text { fill: #beda52; }
@keyframes fa-sway { 50% { rotate: 3deg; } }
@keyframes fa-wave { 0% { opacity: 0; scale: .8; } 35% { opacity: 1; } 100% { opacity: 0; scale: 1.1; } }
@keyframes fa-float { 50% { translate: 0 -10px; } }
@keyframes fa-blob { 50% { scale: 1.04; rotate: 4deg; } }
@media (prefers-reduced-motion: reduce) { .fa-mic, .fa-waves path, .fa-q, .fa-blob { animation: none; } }
@media (max-width: 899px) { .pc-faq__art svg { max-width: 320px; margin-inline: auto; } }

/* latest episodes: no lift on hover (image zoom + arrow only) */
@media (hover: hover) { .pc-ep:hover { translate: 0 var(--py, 0px); box-shadow: inset 0 0 0 1px var(--edge); } }


/* ---- host cards: diamond-glass edges + 3D turn on scroll (hostCards3d() in motion/podcast.ts) ---- */
.pc-hosts { perspective: 1600px; }
.pc-person { transform-style: preserve-3d; }
.pc-person__card { box-shadow: 0 30px 60px -32px rgb(0 0 0 / .55), 0 2px 0 rgb(255 255 255 / .04); transform-style: preserve-3d; will-change: transform; }
/* prism rim: a 1.5px gradient border, brightest at the top-left, with a cool and a lime glint */
.pc-person__card::before { content: ''; position: absolute; inset: 0; z-index: 3; border-radius: inherit; padding: 1.5px; pointer-events: none;
  background: linear-gradient(135deg, rgb(255 255 255 / .95) 0%, rgb(200 230 255 / .55) 18%, rgb(255 255 255 / .08) 40%, rgb(255 255 255 / .04) 60%, rgb(190 218 82 / .55) 82%, rgb(255 255 255 / .8) 100%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0); }
/* inner glass: a soft top highlight and a slow diagonal sheen */
.pc-person__glass { position: absolute; inset: 0; z-index: 2; border-radius: inherit; pointer-events: none; overflow: hidden;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / .35), inset 0 0 0 1px rgb(255 255 255 / .06), inset 0 -40px 60px -40px rgb(0 0 0 / .4); }
.pc-person__glass::after { content: ''; position: absolute; top: -50%; left: -60%; width: 40%; height: 200%; rotate: 20deg;
  background: linear-gradient(90deg, transparent, rgb(255 255 255 / .22), transparent); animation: pc-sheen 6s ease-in-out infinite; }
.pc-person:nth-child(2) .pc-person__glass::after { animation-delay: -2s; } .pc-person:nth-child(3) .pc-person__glass::after { animation-delay: -4s; }
@keyframes pc-sheen { 0%, 55% { translate: 0 0; } 100% { translate: 520% 0; } }
.pc-person__cap { z-index: 4; }
@media (prefers-reduced-motion: reduce) { .pc-person__glass::after { animation: none; display: none; } }
/* card titles share one scale across episodes and topics */
.pc-topic h3, .pc-ep h3 { font-size: clamp(1.02rem, .95rem + .3vw, 1.18rem); }
/* responsive pass: keep the hero's last word with its full stop; blobs off on small phones (they sat behind copy);
   a touch more air between sections on phones */
.nw { white-space: nowrap; }
@media (max-width: 699px) { .pc-page .blob { display: none; } .pc-page .sec { padding-block: 44px; } }
@media (max-width: 379px) { .pc-hero__row .b { font-size: 12px; padding: 0 8px; } }
:root[data-theme='light'] .pc-person__card { box-shadow: none; }

/* community banner, phones v2: shorter photo, tighter type, faces + button on one row, compact stats */
@media (max-width: 699px) {
  .pc-cb { padding: 46vw 18px 20px; gap: 18px; }
  .pc-cb__bg img { height: 64vw; object-position: 70% 30%; }
  .pc-cb::before { background: linear-gradient(180deg, rgb(4 12 12 / 0) 0, rgb(4 12 12 / 0) 28vw, rgb(4 12 12 / .9) 52vw, rgb(4 12 12 / .97) 62vw); }
  .pc-cb__h { font-size: 1.55rem; line-height: 1.12; }
  .pc-cb__big { font-size: 1.55em; }
  .pc-cb__p { margin-top: 10px; font-size: 14px; line-height: 1.5; }
  .pc-cb__row { flex-wrap: nowrap; gap: 12px; margin-top: 18px; }
  .pc-cb__faces img { width: 34px; height: 34px; margin-left: -10px; border-width: 1.5px; }
  .pc-cb__sub { width: auto; flex: 1; min-width: 0; height: 46px; padding: 0 16px; gap: 9px; font-size: 14px; }
  .pc-cb__yt { width: 24px; }
  .pc-cb__arr { display: none; }
  .pc-cb__stats { padding-top: 14px; row-gap: 10px; column-gap: 10px; }
  .pc-cb__stats li { font-size: 13px; gap: 8px; }
  .pc-cb__stats svg { width: 18px; height: 18px; }
}
@media (max-width: 359px) { .pc-cb__faces { display: none; } }
@media (max-width: 699px) { .pc-cb__yt { flex: none; width: 24px; height: 17px; } .pc-cb__sub { white-space: nowrap; } }
@media (max-width: 379px) { .pc-cb__faces img:nth-child(n+3) { display: none; } }

/* "Get featured" popup (FeaturedModal.astro): a spotlight intro (headline with the lime scribble, a live-wave kicker, a
   ticket of perks, a three-step path, who-we-feature chips) beside the entry form. Motion: the intro rises in step; the
   kicker bars dance. Reduced motion keeps everything still. */
.feat-dialog { position: fixed; inset: 0; margin: auto; height: fit-content; width: min(1020px, calc(100vw - 32px)); max-height: calc(100svh - 40px); padding: 0; border: 0; border-radius: 28px;
  background: radial-gradient(120% 60% at 0% 0%, rgb(190 218 82 / .16), transparent 55%), radial-gradient(90% 70% at 100% 100%, rgb(190 218 82 / .10), transparent 60%), var(--card);
  color: var(--ink); box-shadow: 0 40px 100px rgb(0 0 0 / .45), inset 0 0 0 1px var(--edge-2); overflow: auto; }
.feat-dialog[open] { display: block; animation: feat-pop .45s cubic-bezier(.2,.8,.2,1); }
.feat-dialog::backdrop { background: rgb(0 0 0 / .62); backdrop-filter: blur(6px); }
@keyframes feat-pop { from { opacity: 0; transform: translateY(18px) scale(.98); } }

.feat-dialog__close { position: absolute; top: 16px; right: 16px; z-index: 2; display: grid; place-items: center; width: 42px; height: 42px; border: 0; border-radius: 50%;
  background: var(--card-2); color: var(--ink); cursor: pointer; transition: background .25s, transform .25s; }
.feat-dialog__close:hover, .feat-dialog__close:focus-visible { background: #beda52; color: #11150a; transform: rotate(90deg); }

.feat-dialog__inner { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: clamp(26px, 3.2vw, 48px); padding: clamp(26px, 3.6vw, 48px); }
@media (max-width: 800px) { .feat-dialog__inner { grid-template-columns: 1fr; } }

.feat-dialog__intro > * { animation: feat-rise .6s cubic-bezier(.2,.8,.2,1) both; }
.feat-dialog__intro > *:nth-child(2) { animation-delay: .06s; }
.feat-dialog__intro > *:nth-child(3) { animation-delay: .12s; }
.feat-dialog__intro > *:nth-child(4) { animation-delay: .18s; }
.feat-dialog__intro > *:nth-child(5) { animation-delay: .24s; }
.feat-dialog__intro > *:nth-child(6) { animation-delay: .3s; }
@keyframes feat-rise { from { opacity: 0; transform: translateY(12px); } }

.feat-dialog__kicker { display: inline-flex; align-items: center; gap: 12px; padding: 9px 18px 9px 12px; border-radius: 999px; background: #beda52; color: #11150a;
  font-size: 13px; font-weight: 700; letter-spacing: .02em; margin: 0 0 18px; }
.feat-dialog__wave { display: inline-flex; align-items: flex-end; gap: 2px; height: 14px; }
.feat-dialog__wave i { display: block; width: 3px; height: 100%; border-radius: 2px; background: #11150a; transform-origin: bottom; animation: feat-bar 1.1s ease-in-out infinite; }
.feat-dialog__wave i:nth-child(2) { animation-delay: .15s; }
.feat-dialog__wave i:nth-child(3) { animation-delay: .3s; }
.feat-dialog__wave i:nth-child(4) { animation-delay: .45s; }
.feat-dialog__wave i:nth-child(5) { animation-delay: .6s; }
@keyframes feat-bar { 0%, 100% { transform: scaleY(.35); } 50% { transform: scaleY(1); } }

.feat-dialog__h { font-size: clamp(2rem, 1.2rem + 2.6vw, 3.2rem); font-weight: 800; letter-spacing: -0.03em; line-height: 1.02; margin: 0 0 14px; }
.feat-dialog__sub { color: var(--sub-a); font-size: 15px; line-height: 1.6; margin: 0 0 24px; max-width: 44ch; }

.feat-dialog__ticket { position: relative; padding: 18px 20px 16px; border: 1.5px dashed rgb(190 218 82 / .5); border-radius: 18px;
  background: linear-gradient(120deg, rgb(190 218 82 / .10), transparent 65%); margin: 0 0 24px; }
.feat-dialog__ticket::before, .feat-dialog__ticket::after { content: ''; position: absolute; top: 50%; width: 22px; height: 22px; margin-top: -11px; border-radius: 50%; background: var(--card); }
.feat-dialog__ticket::before { left: -12px; }
.feat-dialog__ticket::after { right: -12px; }
.feat-dialog__ticket-h { margin: 0 0 10px; font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: #beda52; }
.feat-dialog__ticket ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.feat-dialog__ticket li { display: flex; align-items: center; gap: 10px; font-size: 15px; color: var(--ink-2); }
.feat-dialog__ticket svg { flex: none; color: #beda52; }

.feat-dialog__path { list-style: none; margin: 0 0 24px; padding: 0; display: grid; gap: 14px; position: relative; }
.feat-dialog__path::before { content: ''; position: absolute; left: 17px; top: 18px; bottom: 18px; width: 2px; background: linear-gradient(#beda52, rgb(190 218 82 / .15)); }
.feat-dialog__path li { position: relative; display: grid; grid-template-columns: 36px 1fr; gap: 14px; align-items: start; }
.feat-dialog__num { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; background: #11150a; color: #beda52; font-weight: 800; font-size: 14px;
  box-shadow: 0 0 0 4px var(--card), 0 0 0 5px rgb(190 218 82 / .35); }
.feat-dialog__path b { display: block; font-size: 15px; color: var(--head-a); margin: 6px 0 2px; }
.feat-dialog__step-d { display: block; font-size: 14px; color: var(--sub-a); line-height: 1.5; }

.feat-dialog__chips { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.feat-dialog__chips li { padding: 7px 14px; border-radius: 999px; font-size: 13px; font-weight: 600; background: var(--card-2); color: var(--ink-2); box-shadow: inset 0 0 0 1px var(--edge-2); }

.feat-dialog__form { align-content: start; }


@media (prefers-reduced-motion: reduce) {
  .feat-dialog[open], .feat-dialog__intro > *, .feat-dialog__wave i { animation: none; }
}

/* Sponsor the show (podcast.astro): three cards, then a CTA row. */
.pc-sponsor__lede { max-width: 56ch; color: var(--sub-a); font-size: 16px; line-height: 1.6; margin: 0 0 clamp(24px, 3vw, 36px); }
.pc-sponsor__n { font-family: var(--font-mark); font-size: 13px; font-weight: 700; letter-spacing: .08em; color: #beda52; }

/* Gallery (podcast.astro): full-width drifting rows, the same structure as the homepage work rows. Each photo is a
   button so it can open the lightbox; the button reset makes it look like the .rows__link tile. */
.pc-rowbtn { display: block; width: 100%; height: 100%; padding: 0; border: 0; background: var(--card); cursor: pointer; font: inherit; }
.pc-rowbtn img { width: 100%; height: 100%; object-fit: cover; display: block; }
.pc-sponsor .sh { margin-bottom: clamp(12px, 1.4vw, 20px); }

/* Get featured button under the guest contact rows: one combined control. A lime pill carries the label and, inside
   its right end, a dark disc with a turning "GET FEATURED" ring in lime and an arrow. The whole pill is one link. It lifts
   on hover, the arrow turns, and the disc pulses softly. Reduced motion keeps everything still. */
.pc-pitch__go { display: flex; justify-content: flex-end; margin: 14px 0 0; }
.pc-badge { perspective: 600px; display: inline-flex; align-items: center; gap: 14px; height: 76px; padding: 0 8px 0 28px; border-radius: 999px; background: #beda52; color: #11150a;
  text-decoration: none; box-shadow: inset 0 3px 0 rgb(255 255 255 / .45), inset 0 -4px 0 rgb(0 0 0 / .18); transition: transform .4s var(--ease), box-shadow .4s; }
.pc-badge__label { font-size: 18px; font-weight: 800; letter-spacing: .005em; }
.pc-badge__disc { position: relative; width: 62px; height: 62px; border-radius: 50%; display: grid; place-items: center; color: #fff; transform-style: preserve-3d;
  background: radial-gradient(circle at 32% 26%, #3a3a3a 0%, #0c0c0c 46%, #000 100%);
  box-shadow: inset -5px -7px 12px rgb(255 255 255 / .08), inset 4px 6px 10px rgb(0 0 0 / .75), 0 0 0 2px #beda52; transition: transform .5s var(--ease), box-shadow .5s; }
.pc-badge__ring { position: absolute; inset: 0; width: 100%; height: 100%; animation: pc-badge-spin 16s linear infinite; }
.pc-badge__ring text { font-family: var(--font-mark); font-size: 21px; font-weight: 800; letter-spacing: .04em; fill: #fff; }
.pc-badge__core { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 50%; color: #11150a; transform: translateZ(10px);
  background: radial-gradient(circle at 35% 30%, #fff 0%, #e9e9e9 55%, #bdbdbd 100%); box-shadow: inset -2px -3px 5px rgb(0 0 0 / .25), 0 4px 10px -2px rgb(0 0 0 / .6); transition: transform .5s var(--ease); }
.pc-badge:hover { transform: translateY(-3px); box-shadow: inset 0 3px 0 rgb(255 255 255 / .5), inset 0 -4px 0 rgb(0 0 0 / .18); }
.pc-badge:hover .pc-badge__disc { transform: rotateX(22deg) rotateY(-16deg) scale(1.08); box-shadow: inset -5px -7px 12px rgb(255 255 255 / .1), inset 4px 6px 10px rgb(0 0 0 / .75), 0 0 0 2px #beda52, 0 22px 30px -10px rgb(0 0 0 / .6); }
.pc-badge:hover .pc-badge__ring, .pc-badge:focus-visible .pc-badge__ring { animation-duration: 5s; }
.pc-badge:hover .pc-badge__core { transform: rotate(-45deg); }
.pc-badge:focus-visible { outline: 3px solid #11150a; outline-offset: 6px; }
@keyframes pc-badge-spin { to { transform: rotate(360deg); } }
@keyframes pc-badge-pulse { 0% { box-shadow: 0 0 0 0 rgb(17 21 10 / .35); } 70%, 100% { box-shadow: 0 0 0 16px rgb(17 21 10 / 0); } }
@media (max-width: 899px) { .pc-pitch__go { justify-content: center; } }
@media (prefers-reduced-motion: reduce) { .pc-badge__ring, .pc-badge__disc { animation: none; } }

/* Sponsor the show: hero with stats, numbered formats, audience chips and the exclusions list. */
.pc-sponsor__hero { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: clamp(24px, 4vw, 56px); align-items: end; margin-bottom: clamp(28px, 3.5vw, 44px); }
@media (max-width: 899px) { .pc-sponsor__hero { grid-template-columns: 1fr; } }
.pc-sponsor__lede { max-width: 52ch; color: var(--sub-a); font-size: 16px; line-height: 1.6; margin: 0 0 22px; }
.pc-sponsor__h3 { font-size: 13px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--mute); margin: 0 0 14px; }
.pc-sponsor__formats { list-style: none; margin: 0 0 clamp(28px, 3.5vw, 44px); padding: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: clamp(12px, 1.4vw, 18px); }
@media (max-width: 1099px) { .pc-sponsor__formats { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 599px) { .pc-sponsor__formats { grid-template-columns: 1fr; } }
.pc-sponsor__format { position: relative; display: flex; flex-direction: column; gap: 8px; padding: clamp(20px, 2vw, 26px); }
.pc-sponsor__format h4 { font-size: 1.1rem; font-weight: 800; letter-spacing: -0.02em; margin: 6px 0 0; padding-right: 44px; }
.pc-sponsor__format p { color: var(--sub-a); font-size: 14px; line-height: 1.55; margin: 0; }
/* Sponsor enquiry popup: the form's checkbox group and selects sit inside the shared .bform look */

/* Sponsor hero: two CTA cards in place of the stats. Each carries an arrow that turns on hover. */
  background: var(--card); color: var(--head-a); text-decoration: none; box-shadow: inset 0 0 0 1px var(--edge-2); transition: background .3s, color .3s, box-shadow .3s, transform .4s var(--ease); }

/* Sponsor hero CTAs are plain buttons, side by side. */
.pc-sponsor__ctas { display: flex; flex-wrap: wrap; justify-content: flex-end; align-items: center; gap: 12px; }
.pc-sponsor__ctas { display: flex; flex-wrap: wrap; justify-content: flex-end; align-items: center; gap: 16px; }
@media (max-width: 899px) { .pc-sponsor__ctas { justify-content: flex-start; } }
/* Each format card carries an arrow disc at its top-right corner. */
.pc-sponsor__go { position: absolute; top: 20px; right: 20px; display: grid; place-items: center; width: 38px; height: 38px; border-radius: 50%; background: #beda52; color: #11150a; transition: transform .4s var(--ease); }
.pc-sponsor__format:hover .pc-sponsor__go { transform: rotate(-45deg); }
/* Sponsor enquiry popup: a plain form, one column. Required fields are marked with an asterisk. */
.sp-dialog { width: min(680px, calc(100vw - 32px)); }

/* Sponsor enquiry popup: a small step-by-step form. One question per step, a progress bar, Back and Next. */
.sp-dialog { width: min(640px, calc(100vw - 32px)); padding: clamp(24px, 3.4vw, 40px); }
.sp-wiz { display: flex; flex-direction: column; gap: 16px; min-height: 360px; }
.sp-wiz__title { font-size: 1.35rem; font-weight: 800; letter-spacing: -0.02em; margin: 0; padding-right: 44px; color: var(--head-a); }
.sp-wiz__top { display: grid; gap: 10px; }
.sp-wiz__count { margin: 0; font-size: 13px; font-weight: 600; letter-spacing: .04em; color: var(--mute); }
.sp-wiz__bar { height: 8px; border-radius: 999px; background: var(--card-2); overflow: hidden; }
.sp-wiz__bar i { display: block; height: 100%; width: 10%; border-radius: 999px; background: #beda52; transition: width .45s var(--ease); }
.sp-step { display: grid; gap: 16px; align-content: center; flex: 1; padding: 6px 0; animation: sp-in .45s var(--ease) both; }
.sp-field { display: grid; gap: 8px; }
.sp-field__l { font-size: 13px; font-weight: 600; color: var(--sub-a); }
.sp-field__l b { color: #beda52; }
.sp-step[hidden] { display: none; }
@keyframes sp-in { from { opacity: 0; transform: translateY(12px); } }
.sp-step__q { font-size: clamp(1.3rem, 1.05rem + .9vw, 1.65rem); font-weight: 800; letter-spacing: -0.02em; line-height: 1.2; color: var(--head-a); }
.sp-step__q b { color: #beda52; }
.sp-step__in { width: 100%; padding: 18px 20px; border: 0; border-radius: 18px; background: var(--card-2); color: var(--ink); font: inherit; font-size: 17px; outline: none; box-shadow: inset 0 0 0 1.5px var(--edge-2); transition: box-shadow .25s; }
.sp-step__in:focus { box-shadow: inset 0 0 0 2px #beda52; }
.sp-step__in::placeholder { color: var(--mute); }
.sp-step__ta { min-height: 120px; resize: vertical; }
.sp-step__sel { position: relative; }
.sp-step__sel select { appearance: none; padding-right: 52px; cursor: pointer; }
.sp-step__chev { position: absolute; right: 18px; top: 50%; translate: 0 -50%; pointer-events: none; color: var(--mute); }
.sp-wiz__nav { display: flex; align-items: center; gap: 12px; margin-top: 4px; }
.sp-wiz__back { border: 0; background: none; padding: 12px 14px; border-radius: 999px; font: inherit; font-weight: 600; color: var(--sub-a); cursor: pointer; }
.sp-wiz__back:disabled { opacity: .35; cursor: default; }
.sp-wiz__next { margin-left: auto; display: inline-flex; align-items: center; gap: 8px; padding: 14px 26px; border: 0; border-radius: 999px; background: #beda52; color: #11150a; font: inherit; font-size: 16px; font-weight: 700; cursor: pointer; transition: transform .3s var(--ease); }
.sp-wiz__next:hover, .sp-wiz__next:focus-visible { transform: translateY(-2px); }
.sp-wiz__send { margin-left: auto; }
.sp-wiz .form__note { margin: 0; }
.sp-wiz [hidden] { display: none !important; }
/* Phones: the Get featured popup is just the form, sized to the screen (the intro is hidden). */
@media (max-width: 800px) {
  .feat-dialog:not(.sp-dialog) .feat-dialog__intro { display: none; }
  .feat-dialog:not(.sp-dialog) .feat-dialog__inner { padding: 56px 18px 18px; }
  .feat-dialog:not(.sp-dialog) .feat-dialog__form .bfield { margin: 0; }
  .feat-dialog:not(.sp-dialog) .feat-dialog__form .bfield input, .feat-dialog:not(.sp-dialog) .feat-dialog__form .bfield select, .feat-dialog:not(.sp-dialog) .feat-dialog__form .bfield textarea { padding-block: 12px; }
  .feat-dialog:not(.sp-dialog) .feat-dialog__form .bfield textarea { min-height: 72px; }
}
/* Phones: a heading row above the form, with the close button placed in its top-right corner. */
.feat-dialog__mhead { display: none; }
@media (max-width: 800px) {
  .feat-dialog:not(.sp-dialog) .feat-dialog__mhead { display: block; padding: 22px 64px 0 20px; }
  .feat-dialog:not(.sp-dialog) .feat-dialog__mtitle { margin: 0; font-size: 20px; font-weight: 800; letter-spacing: -0.02em; line-height: 1.2; color: var(--head-a); }
  .feat-dialog:not(.sp-dialog) .feat-dialog__close { top: 14px; right: 14px; width: 40px; height: 40px; }
  .feat-dialog:not(.sp-dialog) .feat-dialog__inner { padding: 14px 18px 18px; }
}
/* Full-colour client logos are greyed like the others (no tile): dark grey on light, light grey on dark. */
.pc-brands li.is-tile img { filter: grayscale(1) invert(1); }
:root[data-theme='light'] .pc-brands li.is-tile img { filter: grayscale(1); }

/* Phone marquee: the same logos in three auto-scrolling rows (replaces the grid under 520px) */
.pc-brands__marquee { display: none; width: 100%; min-width: 0; }
.pc-brands li { display: grid; place-items: center; }
.pc-brands__track ul { display: flex; margin: 0; padding: 0; list-style: none; }
.pc-brands__track li { flex: 0 0 150px; height: 96px; padding: 18px 16px; border-right: 1px solid var(--edge-2); }
.pc-brands__track { display: flex; width: max-content; animation: pc-brands-run 42s linear infinite; }
.pc-brands__row.is-rev .pc-brands__track { animation-direction: reverse; }
.pc-brands__row:hover .pc-brands__track { animation-play-state: paused; }
@keyframes pc-brands-run { to { transform: translateX(-50%); } }
@media (max-width: 519px) {
  .pc-brands__grid { display: none; }
  .pc-brands__marquee { display: block; }
  .pc-brands__row { width: 100%; min-width: 0; overflow: hidden; border-top: 1px solid var(--edge-2); border-bottom: 1px solid var(--edge-2); }
  .pc-brands__row + .pc-brands__row { border-top: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .pc-brands__track { animation: none; }
  .pc-brands__row { overflow-x: auto; }
}
